  "prediction_basis_card_ids": ["C02", "C04", "C10", "C13", "C15", "C18", "C22", "C24"],
  "claims": [
    {
      "claim": "Validated human sensitization studies reported no sensitization for structurally related terpenoid, cyclic-ester, and glyceryl-ester compounds: α-bisabolol (C02), 4-(isopropyl)-1-methylcyclohexyl acetate (C15, C18), α-methylcyclohexylmethyl acetate (C13, C24), and glyceryl dilaurate (C04, C10, C22).",
      "card_ids": ["C02", "C15", "C18", "C13", "C24", "C04", "C10", "C22"]
    },
    {
      "claim": "Positive human patch-test outcomes are limited to corticosteroids such as clobetasol-17-propionate and hydrocortisone-17-butyrate, whose structural features are absent in the query triterpenoid triester.",
      "card_ids": ["C14", "C16", "C03", "C12", "C21", "C23"]
    },
    {
      "claim": "L3 AOP evidence is not decisive: C25 shows thiol reactivity from autoxidation of α-terpinene, a weak mechanistic concern for the abietane diene, while C33 shows no dendritic-cell activation for the glyceryl triester triolein; neither is a direct sensitization outcome.",
      "card_ids": ["C25", "C33"]
    },
    {
      "claim": "L4 phototoxicity, irritation, and local-damage records are out of scope for the sensitization endpoint; negative phototoxicity for triisostearin (C37, C40) and irritation findings (C42, C45) do not change the prediction.",
      "card_ids": ["C37", "C40", "C42", "C45"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "phototoxicity_irritation_local_damage",
      "applicability": "not_applicable",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C37", "C38", "C39", "C40", "C41", "C42", "C43", "C44", "C45", "C46", "C47", "C48"]
    }
  ],
  "evidence_gaps": [
    "No direct experimental sensitization data exist for the query glyceryl triabietate.",
    "Autoxidation/hydroperoxide formation by the abietane diene is inferred from α-terpinene (C25), not measured for the query.",
    "No human or in vivo induction data specifically for rosin/abietane esters.",
    "Skin delivery of the 945 Da, highly lipophilic triester to viable epidermis is uncertain."
  ],
  "decision_summary": "Predicted no_risk. The most transferable experimental evidence is human negative sensitization data for structurally related terpenoid, cyclic-ester, and glyceryl-ester compounds. L4 phototoxicity/irritation/local-damage records are out of scope and do not alter the decision. Confidence remains low because no query-specific sensitization data are available."
}
